package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.*;

class CommandLine_GetOptionValuesTest {

    /**
     * Test helper: subclass CommandLine to control/observe behavior of getOptionValues(String).
     */
    static class TestableCommandLine extends CommandLine {
        String lastOptionName;
        boolean forceNullReturn;

        TestableCommandLine() {
            super();
        }

        @Override
        public String[] getOptionValues(final String optionName) {
            this.lastOptionName = optionName;
            if (forceNullReturn) {
                return null;
            }
            return new String[] { "val-for-" + optionName };
        }
    }

    @Test
    void returnsNullWhenOptionGroupIsNull() {
        CommandLine cmd = new TestableCommandLine();
        assertNull(cmd.getOptionValues((OptionGroup) null));
    }

    @Test
    void returnsNullWhenOptionGroupNotSelected() {
        CommandLine cmd = new TestableCommandLine();
        OptionGroup group = new OptionGroup();
        // By default nothing is selected
        assertFalse(group.isSelected());
        assertNull(cmd.getOptionValues(group));
    }

    @Test
    void delegatesToGetOptionValuesWhenSelected() throws Exception {
        TestableCommandLine cmd = new TestableCommandLine();
        OptionGroup group = new OptionGroup();

        // set the private 'selected' field reflectively to avoid needing an Option instance
        Field selectedField = OptionGroup.class.getDeclaredField("selected");
        selectedField.setAccessible(true);
        selectedField.set(group, "foo");

        assertTrue(group.isSelected());
        String[] result = cmd.getOptionValues(group);

        assertNotNull(result);
        assertArrayEquals(new String[] { "val-for-foo" }, result);
        assertEquals("foo", cmd.lastOptionName);
    }

    @Test
    void delegatesAndReturnsNullWhenUnderlyingReturnsNull() throws Exception {
        TestableCommandLine cmd = new TestableCommandLine();
        cmd.forceNullReturn = true;
        OptionGroup group = new OptionGroup();

        Field selectedField = OptionGroup.class.getDeclaredField("selected");
        selectedField.setAccessible(true);
        selectedField.set(group, "bar");

        assertTrue(group.isSelected());
        String[] result = cmd.getOptionValues(group);

        assertNull(result);
        assertEquals("bar", cmd.lastOptionName);
    }
}

